if (polygon.empty())
    return CGAL::ON_UNBOUNDED_SIDE;

int n = polygon.size();
int count = 0;
const Point_2& p = point;

for (int i = 0; i < n; ++i) {
    const Point_2& a = polygon[i];
    const Point_2& b = polygon[(i + 1) % n];

    // Check if the point is on the current edge
    if (a == b) {
        if (a == p)
            return CGAL::ON_BOUNDARY;
        continue;
    }

    // Check if the point is on the vertex
    if (a == p || b == p)
        return CGAL::ON_BOUNDARY;

    // Check if the point is on the edge
    if (CGAL::collinear(a, b, p)) {
        if ((p.x() - a.x()) * (p.x() - b.x()) <= 0 && (p.y() - a.y()) * (p.y() - b.y()) <= 0)
            return CGAL::ON_BOUNDARY;
    }

    // Check if the edge intersects the ray
    if ((a.y() > p.y()) != (b.y() > p.y())) {
        // Compute the x-intersection of the edge with the ray
        double x_intersect = (b.x() - a.x()) * (p.y() - a.y()) / (b.y() - a.y()) + a.x();

        if (p.x() <= x_intersect)
            ++count;
    }
}

return (count % 2) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;

